static int32_t HandleHungupResult(int32_t result)
{
    LV_LOG_USER("[%s],hungup result = %d", __func__, result);
    if(0 != result) {
        /* wait remote accept call,do nothing */
    } else {
        LV_LOG_USER("[%s],hungup fail", __func__);
    }

    return 0;
}

void outgoing_win_active(lv_obj_t *win, void *p_param)
{
    char num[CALL_PHONE_NUMBER_LEN_MAX] = {0};

    ui_outgoing_init();

    call_flow_get_phonenum(num);
    if(call_flow_is_emergency_number(num)) {
        lv_label_set_text(ui_LblOutgoingPhoneNum, "Emergency Number");
    }else {
        lv_label_set_text(ui_LblOutgoingPhoneNum, num);
    }
    lv_group_add_obj(lv_group_get_default(), ui_Outgoing);
}

void outgoing_win_deactive(lv_obj_t *win, void *p_param)
{
    lv_obj_del(ui_Outgoing);
}
void outgoing_win_focus(lv_obj_t * win, void * p_param)
{
    lv_disp_load_scr(ui_Outgoing);
    SHOW_STATUSBAR;
    lv_group_focus_obj(ui_Outgoing);
}
